import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·11","description":"易小帖 - 卷三·11","frontmatter":{"title":"卷三·11","description":"易小帖 - 卷三·11"},"headers":[],"relativePath":"zh/classics/yixiaotie/079.md","filePath":"zh/classics/yixiaotie/079.md"}'),o={name:"zh/classics/yixiaotie/079.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·11",tabindex:"-1"},[r("卷三·11 "),e("a",{class:"header-anchor",href:"#卷三·11","aria-label":"Permalink to “卷三·11”"},"​")],-1),e("p",null,"大衍之數五十，以「天一地二天三地四天五地六天七地八天九地十」之數較之，則天數二十有五，地數三十。其數不合，於是漢儒立說紛紛而起。然大概牽強附會，並無一當。惟唐崔憬闡陰陽老少之說，謂：陽從三起，順數至五七九而成老陽，不取一數。陰從二起，逆數至十八六而成老陰，不取四數。去一數四數，而適得五十，此稍近理。然夫子傳文不然，其於大衍五十之後，即接「天數五，地數五，五位相得而各有合」語，明明以此作五十之註，謂天數與地數相合，各有生成之數，而生數止於五，成數止於十，雖合數五十有五，而生成大數止得五十，此夫子自為釋者。若宋人朱元昇作《圖書合數》，謂河圖之數四十有五（此依劉長民倒置之說）合之洛書之數五十有五，共百數也，而分陰分陽，則陽數剛五十，陰數亦剛五十，無少偏缺。所謂大衍之數五十者如此，夫合百數而止取五十。取陽乎？抑取陰乎？且天數地數，止有此數。今所稱圖書者各言之耳。以其所各言者而並數之，將所雲天數五者，今天數有十。所謂坎一離二者，今有坎二離四，此大亂之道也。夫夫子明數，其數而指實之，曰天數二十有五，地數三十，而此反曰天數五十，地數五十。夫子明曰凡天地之數五十有五，而此反曰天地之數一百，可乎？陳氏河圖，原竊鄭康成大衍之數註，故五十五數與夫子所言之數合。若洛書則竊《乾鑿度》太乙下九宮法，其所雲四十五數，則自有易以來並無此數，不惟夫子傳中無此，即漢儒田何以後，下至唐儒孔陸諸徒，言易千家，亦何曾曰天壤間有四十五數之易。而宋後丹竈之家，亂及九筮，六經從此掃地矣。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
